export function GreysonScoreCard({ totalScore, classification, breakdown }: GreysonScoreCardProps) {
    if (!breakdown) return <div>NO BREAKDOWN</div>;

    return (
        <div className="p-4 border border-blue-500 bg-blue-100 text-blue-900 font-bold text-xl">
            SIMPLE RENDER TEST: Score {totalScore}
        </div>
    );
}
